mapper.select:
SELECT operation, actor_id, idempotency_key, fingerprint, page_id, revision_id, created_at
FROM t_pa_idempotency
WHERE operation = #{operation} AND actor_id = #{actorId} AND idempotency_key = #{idempotencyKey}

mapper.delete:
DELETE FROM t_pa_idempotency
WHERE created_at < #{cutoff}
LIMIT #{batchSize}
